targets.expr:
histogram_quantile(
    0.95,
    sum by (le, service, action) (
      rate(
        {
          __name__=~".+_request_durations_histogram_seconds_bucket",
          job=~"application-(auth|catalog|cart)",service=~"${services:regex}",
          action=~".+-.+",
          action!="all"
        }[5m]
      )
    )
  )

(
  (node_filesystem_size_bytes{node="$nodeInstance", job="node-exporter", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{node="$nodeInstance", job="node-exporter", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{node="$nodeInstance", job="node-exporter", mountpoint="/", fstype!="rootfs"}
) * 100
